NAME = 'CzeCSP: Czech Český studijní překlad'
BOOK = 'Galatians'

CHAPTERS = {
    1: {
        1: 'Pavel, apoštol vyslaný ne od lidí nebo skrze člověka, ale skrze Ježíše Krista a Boha Otce, který ho vzkřísil z mrtvých,',
        2: 'a všichni bratři, kteří jsou se mnou, sborům Galacie:',
        3: 'Milost vám a pokoj od Boha ⌈našeho Otce a Pána⌉ Ježíše Krista,',
        4: 'který dal sám sebe za naše hříchy, aby nás vysvobodil z tohoto přítomného zlého věku podle vůle našeho Boha a Otce,',
        5: 'jemuž buď sláva na věky věků. Amen.',
        6: 'Divím se, že se od toho, který vás povolal ⌈ Kristovou milostí⌉, tak rychle odvracíte k jinému evangeliu.',
        7: 'Není jiné evangelium, ale jsou někteří, kteří vás uvádějí ve zmatek a chtějí ⌈Kristovo evangelium⌉ překroutit.',
        8: 'Ale i kdybychom [vám] my nebo sám anděl z nebe ⌈zvěstoval v evangeliu⌉ něco ⌈jiného než⌉ to, co jsme vám zvěstovali, budiž proklet!',
        9: 'Jak jsme řekli dříve, i nyní říkám znovu: Jestliže vám někdo ⌈zvěstuje jako evangelium⌉ něco mimo to, co jste přijali, budiž proklet!',
        10: 'Získávám si teď lidi, nebo Boha? Či se snažím líbit lidem? Kdybych se chtěl ještě líbit lidem, nebyl bych Kristův otrok.',
        11: 'Oznamuji vám, bratři, že evangelium, které jsem vám zvěstoval, není podle člověka.',
        12: 'Neboť jsem je nepřevzal ani se mu nenaučil od člověka, ale skrze zjevení Ježíše Krista.',
        13: 'Vždyť jste slyšeli o mém někdejším počínání, když jsem byl v židovství, že jsem do krajnosti pronásledoval Boží církev a ⌈ničil ji⌉.',
        14: 'Předčil jsem v židovství mnohé vrstevníky svého rodu, neboť jsem byl mimořádný horlivec pro otcovské tradice.',
        15: 'Když se však [Bohu], který mne oddělil již ⌈v lůně⌉ mé matky a povolal svou milostí, zalíbilo',
        16: 'zjevit ve mně svého Syna, abych evangelium o něm hlásal mezi pohany, neporadil jsem se hned ⌈s tělem a krví⌉,',
        17: 'ani jsem nevystoupil do Jeruzaléma k těm, kdo byli apoštoly dříve než já, nýbrž odešel jsem do Arábie a pak jsem se zase vrátil do Damašku.',
        18: 'Potom po třech letech jsem vystoupil do Jeruzaléma, abych se seznámil s Kéfou, a zůstal jsem u něho patnáct dní.',
        19: 'Nikoho jiného z apoštolů jsem neviděl, jen Jakuba, Pánova bratra.',
        20: 'Hle, před Bohem prohlašuji, že to, co vám píšu, není lež.',
        21: 'Potom jsem šel do končin Syrie a Kilikie.',
        22: 'Ve sborech v Judsku, které jsou v Kristu, mě osobně neznali.',
        23: 'Pouze o mně slýchávali, že ten, který nás kdysi pronásledoval, zvěstuje nyní víru, kterou kdysi ničil,',
        24: 'a slavili kvůli mně Boha.',
    },
    2: {
        1: 'Potom po čtrnácti letech jsem opět vystoupil do Jeruzaléma s Barnabášem a vzal jsem s sebou i Tita.',
        2: 'Vystoupil jsem tam ⌈na základě⌉ zjevení a předložil jsem jim evangelium, které hlásám mezi pohany; předložil jsem je však v soukromí těm, kteří jsou uznáváni, abych snad neběžel nebo nebyl běžel nadarmo.',
        3: 'Ale ani Titus, který byl se mnou a je Řek, nebyl přinucen dát se obřezat,',
        4: '⌈jak to chtěli ti⌉ falešní bratři, vetřelci, kteří se tam vloudili, aby vyšpehovali naši svobodu, kterou máme v Kristu Ježíši, a aby nás zotročili.',
        5: 'Ale těm jsme ani na chvíli neustoupili a nepodřídili jsme se jim, aby vám zůstala pravda evangelia.',
        6: 'Od těch, kteří něco znamenají -- na tom, jací kdysi byli, mi nezáleží, protože Bůh nepřijímá ⌈člověka podle významu jeho osoby⌉ -- ti uznávaní mně tedy nic dalšího neuložili.',
        7: 'Naopak když uviděli, že mi bylo svěřeno evangelium ⌈pro neobřezané⌉ jako Petrovi ⌈pro obřezané⌉ --',
        8: 'neboť ten, který působil u Petra k apoštolství ⌈pro obřezané⌉, působil i u mne k apoštolství pro pohany --;',
        9: 'když tedy poznali tu milost, která mi byla dána, po dali Jakub, Kéfas a Jan, kteří byli uznáváni za sloupy církve, mně i Barnabášovi pravici na důkaz společenství, abychom my šli mezi pohany a oni mezi obřezané.',
        10: 'Jen žádali, abychom pamatovali na ⌈ jejich chudé⌉, což jsem právě i já sám pilně činil.',
        11: 'Ale když přišel Kéfas do Antiochie, postavil jsem se proti němu tváří v tvář, neboť ⌈si zasloužil odsouzení⌉.',
        12: 'Než totiž přišli někteří od Jakuba, jídával společně s pohany. Když však přišli, začal couvat a oddělovat se, protože se bál těch, kteří byli z obřezaných.',
        13: 'A spolu s ním upadli do pokrytectví i ostatní Židé, takže i Barnabáš byl stržen jejich pokrytectvím.',
        14: 'Když jsem však uviděl, že nejdou rovně podle pravdy evangelia, řekl jsem Kéfovi přede všemi: „Jestliže ty, ač jsi Žid, žiješ pohansky, a ne židovsky, jak to, že nutíš pohany, aby žili jako Židé?“',
        15: 'My jsme rodem Židé, a ne hříšníci z pohanů;',
        16: 'když [však] víme, že člověk není ospravedlňován ze skutků Zákona, nýbrž skrze víru v Ježíše Krista, i my jsme v Krista Ježíše uvěřili, abychom byli ospravedlněni z víry Kristovy, a ne ze skutků Zákona, protože ze skutků Zákona nebude ospravedlněn žádný člověk.',
        17: 'Jestliže však i my, kteří hledáme ospravedlnění v Kristu, jsme byli shledáni hříšnými, je snad proto Kristus služebníkem hříchu? Naprosto ne!',
        18: 'Neboť jestliže znovu buduji to, co jsem zbořil, představuji sebe jako přestupníka.',
        19: 'Vždyť já jsem skrze Zákon umřel Zákonu, abych žil Bohu. S Kristem jsem ukřižován:',
        20: 'Nežiji už já, ale žije ve mně Kristus. Život, který nyní žiji v těle, žiji ve víře v ⌈Syna Božího⌉, který si mne zamiloval a vydal sebe samého za mne.',
        21: 'Neodmítám milost Boží, neboť jestliže spravedlnost je ze Zákona, potom Kristus zemřel nadarmo.',
    },
    3: {
        1: 'Ó, nerozumní Galaťané, kdo vás očaroval, vás, kterým byl před očima vykreslen Ježíš Kristus ukřižovaný?',
        2: 'Toto jediné se chci od vás dovědět: Přijali jste Ducha ⌈na základě⌉ skutků Zákona, nebo ⌈na základě⌉ slyšení víry?',
        3: 'To jste tak nerozumní? Začali jste Duchem, a nyní dokončujete tělem?',
        4: 'Tolik jste vytrpěli nadarmo? Jestliže to skutečně bylo nadarmo!',
        5: 'Tedy ten, který vás vystrojuje Duchem a působí ⌈mezi vámi⌉ mocné věci, činí tak ⌈na základě⌉ skutků Zákona, nebo ⌈na základě⌉ slyšení víry?',
        6: 'Je tomu jako s Abrahamem: uvěřil Bohu a bylo mu to počteno za spravedlnost.',
        7: 'Vězte tedy, že ti, kdo jsou z víry, jsou synové Abrahamovi.',
        8: 'Písmo předvídalo, že Bůh ospravedlní pohany ⌈na základě⌉ víry; dopředu oznámilo Abrahamovi: V tobě budou požehnány všechny národy.',
        9: 'Takže ti, kdo jsou z víry, ⌈docházejí požehnání⌉ s věřícím Abrahamem.',
        10: 'Neboť všichni ti, kteří jsou ze skutků Zákona, jsou pod prokletím, neboť je napsáno: Proklet je každý, kdo nezůstává ve všem tom, co je napsáno v knize Zákona, aby to činil.',
        11: 'Je jasné, že Zákonem není nikdo před Bohem ospravedlňován, neboť spravedlivý bude živ z víry.',
        12: 'Zákon však není z víry, nýbrž: Kdo ⌈ty věci⌉ bude činit, bude v nich živ.',
        13: 'Kristus nás vykoupil z prokletí Zákona tím, že se stal za nás prokletím, neboť je napsáno: Proklet je každý, kdo je pověšen na dřevě.',
        14: 'To proto, aby k pohanům přišlo to Abrahamovo požehnání v Kristu Ježíši a abychom skrze víru přijali zaslíbení Ducha.',
        15: 'Bratři, ⌈po lidsku⌉ pravím: Už potvrzenou závěť člověka nikdo neruší ani k ní nic nepřipojuje.',
        16: 'Zaslíbení byla řečena Abrahamovi a jeho potomku. Písmo neříká: a potomkům, jako by jich bylo mnoho, ale jedná se jen o jednoho: a tvému potomku, a tím potomkem je Kristus.',
        17: 'Říkám tedy toto: Zákon, jenž byl dán po čtyřech stech třiceti letech, nemůže zrušit smlouvu již předtím právoplatně potvrzenou od Boha, a tak zmařit to zaslíbení.',
        18: 'Neboť jestliže je to dědictví ze Zákona, ne ní již ze zaslíbení; Abrahamovi je však Bůh daroval skrze zaslíbení.',
        19: 'K čemu tedy Zákon? Byl přidán kvůli přestoupením, dokud by nepřišel potomek, kterému bylo dáno zaslíbení. Byl ustanoven skrze anděly rukou prostředníka.',
        20: 'Prostředník ⌈však není jen pro jednu stranu ⌉, Bůh však je jeden.',
        21: 'Staví se tedy Zákon proti [Božím] zaslíbením? Rozhodně ne! Neboť kdyby byl dán Zákon, který by byl mocen obživit, byla by spravedlnost vskutku ze Zákona.',
        22: 'Avšak Písmo uzavřelo všechno pod hřích, aby bylo dáno zaslíbení z víry Ježíše Krista těm, kdo věří.',
        23: 'Dokud nepřišla víra, byli jsme hlídáni pod Zákonem, uzavíráni pro víru, která měla být zjevena,',
        24: 'takže se Zákon stal naším vychovatelem ke Kristu, abychom byli ospravedlněni z víry.',
        25: 'Když však přišla víra, nejsme již pod řízeni vychovateli.',
        26: 'Neboť všichni jste synové Boží skrze víru v Kristu Ježíši.',
        27: 'Vždyť vy všichni, kteří jste byli v Krista pokřtěni, Krista jste oblékli.',
        28: 'Již není Žid ani Řek, již není otrok ani svobodný, již není muž ani žena, neboť vy všichni jste jedno v Kristu Ježíši.',
        29: 'A jestliže jste Kristovi, jste símě Abrahamovo, dědicové podle zaslíbení.',
    },
    4: {
        1: 'Říkám však: Pokud je dědic nezletilý, v ničem se neliší od otroka, ač je pánem všeho.',
        2: 'Je pod řízen poručníkům a správcům až do doby předem určené otcem.',
        3: 'Stejně i my, když jsme byli nezletilí, byli jsme v otroctví pod živly světa.',
        4: 'Když však přišla plnost času, vyslal Bůh svého Syna, narozeného z ženy, narozeného pod Zákonem,',
        5: 'aby vykoupil ty, kdo byli pod Zákonem, a abychom přijali synovství.',
        6: 'A protože jste synové, vyslal Bůh ducha svého Syna do našich srdcí, ⌈ ducha, který volá⌉: Abba, Otče.',
        7: 'Takže už nejsi otrok, ale syn. A když syn, tedy i dědic ⌈skrze Boha⌉.',
        8: 'V čase, kdy jste neznali Boha, otročili jste těm, kteří svou přirozeností nejsou bohy.',
        9: 'Nyní však, když jste poznali Boha, nebo spíše když jste byli od Boha poznáni, jak to, že se zase obracíte k těm slabým a ubohým živlům, kterým zase znovu chcete otročit?',
        10: 'Zachováváte dny, měsíce, období a roky!',
        11: 'Bojím se o vás, abych se pro vás nakonec nelopotil nadarmo.',
        12: 'Prosím vás, bratři, buďte jako já, protože i já jsem jako vy. Ničím jste mi neublížili.',
        13: 'Víte, že jsem vám poprvé v slabosti těla hlásal evangelium.',
        14: 'A touto zkouškou, ⌈která se týkala mého tělesného stavu⌉, jste nepohrdli ani ⌈jste se neodvrátili⌉, ale přijali jste mne jako posla Božího, jako Krista Ježíše.',
        15: 'Kde je tedy to vaše blahoslavenství? Neboť vám vydávám svědectví, že kdyby to bylo možné, byli byste si vyloupli oči a dali je mně.',
        16: 'Takže jsem se stal vaším nepřítelem, když vám říkám pravdu?',
        17: 'Oni pro vás horlí, ale ne k dobrému; chtějí vás odloučit, abyste horlili pro ně.',
        18: 'Je dobré horlit v dobrém vždycky, a ne jenom tehdy, když jsem u vás přítomen.',
        19: 'Mé děti, které opět v bolestech rodím, dokud ve vás nebude zformován Kristus;',
        20: 'chtěl bych teď být u vás a změnit svůj hlas, neboť si s vámi nevím rady.',
        21: 'Řekněte mi vy, kteří chcete být pod Zákonem: Což neslyšíte Zákon?',
        22: 'Neboť je napsáno, že Abraham měl dva syny, jednoho z otrokyně a druhého ze svobodné.',
        23: 'Ten z otrokyně se však narodil podle těla, ten ze svobodné skrze zaslíbení.',
        24: 'Je to řečeno alegoricky: Tyto ženy jsou dvě smlouvy, jedna z hory Sinaj, která rodí děti do otroctví, a to je Hagar.',
        25: 'Hagar je hora Sinaj v Arábii. Ta odpovídá nynějšímu Jeruzalému, neboť ten je v otroctví se svými dětmi.',
        26: 'Ale horní Jeruzalém je svobodný a ten je ⌈naší matkou⌉.',
        27: 'Neboť je napsáno: Raduj se neplodná, která nerodíš, propukni v jásot a vykřikni ty, která nemáš porodní bolesti, protože mnoho je dětí té osamělé, více než té, která má muže.',
        28: 'Vy však, bratři, jste jako Izák dětmi zaslíbení.',
        29: 'Ale jako tenkrát ten, který byl zrozený podle těla, pronásledoval toho, který se narodil podle Ducha, tak je tomu i nyní.',
        30: 'Co však praví Písmo? Vyžeň otrokyni i jejího syna, neboť syn otrokyně nebude dědicem spolu se synem svobodné.',
        31: 'Proto, bratři, nejsme děti otrokyně, nýbrž té svobodné.',
    },
    5: {
        1: '⌈ K té svobodě nás Kristus osvobodil. Stůjte tedy pevně⌉ a nenechte se opět podrobit pod jho otroctví.',
        2: 'Hle, já, Pavel, vám pravím, že dáváte–li se obřezávat, Kristus vám nic neprospěje.',
        3: 'A znova dosvědčuji každému člověku, který se dává obřezat, že je povinen zachovat celý Zákon.',
        4: 'Zbavili jste se Krista, vy, kteří hledáte ospravedlnění v Zákoně; vypadli jste z milosti.',
        5: 'Neboť my v Duchu ⌈na základě⌉ víry očekáváme naději spravedlnosti.',
        6: 'Neboť v Kristu Ježíši nic neznamená obřízka ani neobřízka, ale víra působící skrze lásku.',
        7: 'Běželi jste dobře. Kdo vám zabránil poslouchat pravdu?',
        8: 'To přemlouvání ne ní od toho, který vás povolává.',
        9: 'Trocha kvasu prokvasí celé těsto.',
        10: 'Jsem o vás přesvědčen v Pánu, že nebudete smýšlet jinak. A ten, kdo vás mate, ponese odsouzení, ať je to kdokoliv.',
        11: 'Bratři, jestliže dosud hlásám obřízku, proč jsem ještě pronásledován? Pak by se ztratilo pohoršení kříže.',
        12: 'Ti, kdo vás znepokojují obřízkou, ať ⌈se třeba i vyklestí⌉.',
        13: 'Byli jste přece povoláni do svobody, bratři. Jen aby se vám ta svoboda ne stala záminkou pro tělo. Vy však skrze lásku služte jedni druhým.',
        14: 'Neboť celý Zákon je naplněn v jednom slovu: Budeš milovat svého bližního jako sebe samého.',
        15: 'Jestliže se však navzájem koušete a požíráte, dávejte si pozor, abyste nebyli jeden druhým pohlceni.',
        16: 'Říkám však: Duchem choďte a žádost těla nedokonáte.',
        17: 'Tělo žádá proti Duchu a Duch proti tělu, neboť stojí navzájem proti sobě, abyste nečinili to, co byste chtěli.',
        18: 'Jste–li vedeni Duchem, nejste pod Zákonem.',
        19: 'Skutky těla jsou zřejmé, jsou to [cizoložstvo,] smilstvo, nečistota, bezuzdnost,',
        20: 'modloslužba, čarování, nepřátelství, ⌈svár, žárlivost⌉, hněvy, soupeření, rozdělení, sekty,',
        21: 'závisti, [vraždy,] opilství, hýření a podobné věci. To vám předpovídám, jak jsem již dříve řekl, že ti, kdo takové věci dělají, neobdrží dědičně Boží království.',
        22: 'Ovocem Ducha je však láska, radost, pokoj, trpělivost, laskavost, dobrota, věrnost,',
        23: 'mírnost, sebeovládání. Proti takovým není žádný zákon.',
        24: 'Ti, kdo patří Kristu [Ježíši], ukřižovali tělo s jeho vášněmi a žádostmi.',
        25: '⌈Jsme–li Duchem živi⌉, Ducha také následujme.',
        26: '⌈Nehledejme marnou slávu⌉, navzájem se neprovokujme a jedni druhým nezáviďme.',
    },
    6: {
        1: 'Bratři, kdyby byl někdo i přistižen v nějakém přestoupení, vy, kdo jste duchovní, napravujte takového člověka v duchu mírnosti a dávej si každý pozor sám na sebe, abys i ty neupadl do pokušení.',
        2: 'Neste břemena jedni druhých, a tak naplňte zákon Kristův.',
        3: 'Myslí–li si totiž někdo, že je něco, ačkoli nic není, klame sám sebe.',
        4: 'Každý ať zkoumá své jednání, a pak se bude moci chlubit pouze ⌈s ohledem na⌉ sebe, a ne na druhého.',
        5: 'Neboť každý ponese svůj vlastní náklad.',
        6: 'Ten, kdo je vyučován slovu, nechť se sdílí ve všech dobrých věcech s tím, kdo vyučuje.',
        7: '⌈Nemylte se⌉, Bohu se nikdo nebude vysmívat. Co člověk zaseje, to také sklidí.',
        8: 'Kdo zasévá pro své tělo, z těla sklidí zkázu; kdo zasévá pro Ducha, z Ducha sklidí život věčný.',
        9: 'V činění dobra neochabujme; nezemdlíme–li, budeme ve svůj čas žnout.',
        10: 'Tak tedy dokud máme čas, čiňme dobro všem, zvláště však ⌈těm, kteří patří do rodiny⌉ víry.',
        11: 'Pohleďte, jak velkými písmeny jsem vám napsal vlastní rukou!',
        12: 'Ti, kteří chtějí vypadat dobře ⌈před lidmi⌉, vás nutí dávat se obřezat, jen aby nebyli pronásledováni pro kříž Kristův.',
        13: 'Neboť ani ti obřezaní sami Zákon nezachovávají, ale na vás chtějí, abyste se dávali obřezat, aby se mohli pochlubit vaším tělem.',
        14: 'Kéž se mi nestane, abych se chlubil, leda křížem našeho Pána Ježíše Krista, skrze nějž je pro mne svět ukřižován a já pro svět.',
        15: 'Neboť ani obřízka ani neobřízka nic není, nýbrž nové stvoření.',
        16: 'A na ty, kdo se budou držet tohoto pravidla, ať přijde pokoj a milosrdenství, též na Boží Izrael.',
        17: 'Ať mi už nikdo nepůsobí potíže, vždyť já nosím na svém těle ⌈znaky toho, že patřím ⌉ Ježíši.',
        18: 'Milost našeho Pána Ježíše Krista buď s vaším duchem, bratři. Amen.',
    },
}
